import ee
import math

# Initialize
try:
    ee.Initialize()
except Exception:
    ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
kabul = ee.Geometry.Point([69.2075, 34.5553])
miles_to_m = 1609.34
geom = kabul.buffer(30 * miles_to_m)

periods = {
    2017: ('2017-02-01', '2017-03-01'),
    2018: ('2018-02-01', '2018-03-01'),
}

def get_month_stats(year):
    start, end = periods[year]
    # Primary: 3-hourly GLDAS
    try:
        col = (ee.ImageCollection('NASA/GLDAS/V021/NOAH/G025/T3H')
               .filterDate(start, end)
               .filterBounds(geom))
        n = col.size().getInfo()
    except Exception as e:
        print(f"{year} Error accessing GLDAS T3H: {e}")
        return {'status': 'D'}
    if n == 0:
        # Fallback: monthly GLDAS
        try:
            col = (ee.ImageCollection('NASA/GLDAS/V021/NOAH/G025/M')
                   .filterDate(start, end)
                   .filterBounds(geom))
            n = col.size().getInfo()
            src = 'M'
        except Exception as e:
            print(f"{year} Error accessing GLDAS M: {e}")
            return {'status': 'D'}
        if n == 0:
            # No images available
            return {'status': 'C1', 'imgCount': 0, 'src': 'None'}
    else:
        src = 'T3H'
    # Detect SWE band name robustly
    try:
        band_names = col.first().bandNames().getInfo()
        swe_band = None
        for b in band_names:
            if 'SWE' in b.upper():
                swe_band = b
                break
        if swe_band is None:
            return {'status': 'D'}
        col = col.select([swe_band], ['SWE'])
    except Exception as e:
        print(f"{year} Band selection error: {e}")
        return {'status': 'D'}

    # Monthly mean SWE image
    img = col.mean()

    # Compute stats over region
    try:
        reducers = ee.Reducer.mean().combine(reducer2=ee.Reducer.count(), sharedInputs=True)
        stats = img.reduceRegion(
            reducer=reducers,
            geometry=geom,
            scale=25000,
            maxPixels=1e9,
        )
        mean_val = stats.get('SWE_mean').getInfo()
        count = stats.get('SWE_count').getInfo()
    except Exception as e:
        print(f"{year} reduceRegion error: {e}")
        return {'status': 'D'}

    # Validate pixels
    if count is None or int(count) == 0:
        return {'status': 'C2', 'imgCount': n, 'src': src, 'pixels': int(count) if count is not None else 0}

    # Validate value
    if mean_val is None or (isinstance(mean_val, float) and (math.isnan(mean_val) or math.isinf(mean_val))) or mean_val < 0:
        return {'status': 'C3', 'imgCount': n, 'src': src, 'pixels': int(count)}

    return {
        'status': 'OK',
        'imgCount': n,
        'src': src,
        'pixels': int(count),
        'mean_mm': float(mean_val)  # kg/m^2 equals mm of water
    }

# Run for both years
res17 = get_month_stats(2017)
res18 = get_month_stats(2018)

# Handle non-OK statuses
for res, yr in [(res17, 2017), (res18, 2018)]:
    if res.get('status') == 'D':
        print(f"{yr} Failure: Dataset/band/method error.")
        print("D")
        raise SystemExit()
    if res.get('status') == 'C1':
        print(f"{yr} Images: 0")
        print("C1")
        raise SystemExit()
    if res.get('status') == 'C2':
        print(f"{yr} Images: {res.get('imgCount', 0)} (src={res.get('src','?')}), Valid Pixels: 0")
        print("C2")
        raise SystemExit()
    if res.get('status') == 'C3':
        print(f"{yr} Images: {res.get('imgCount', 0)} (src={res.get('src','?')}), Calculation failed.")
        print("C3")
        raise SystemExit()

# 5. Validation & Final Answer
print("Region: 30-mile radius around Kabul (69.2075, 34.5553)")
print(f"2017 Images: {res17['imgCount']} (src={res17['src']}), Valid Pixels: {res17['pixels']}, SWE mean (mm): {res17['mean_mm']:.2f}")
print(f"2018 Images: {res18['imgCount']} (src={res18['src']}), Valid Pixels: {res18['pixels']}, SWE mean (mm): {res18['mean_mm']:.2f}")
diff = res18['mean_mm'] - res17['mean_mm']
print(f"Difference (2018 - 2017) SWE mean: {diff:.2f} mm")

# Decide final answer
if res18['mean_mm'] > res17['mean_mm']:
    print("A")
else:
    print("B")
